def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def esc(x):return html.escape(str(x))
def uri(p,mime):return 'data:'+mime+';base64,'+base64.b64encode(Path(p).read_bytes()).decode()
def clean(df):return json.loads(df.to_json(orient='records'))
def table(headers,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def detail(title,body):return '<details><summary>'+esc(title)+'</summary>'+body+'</details>'
def figure(svg,legend,caption):return '<figure><img class="artwork" src="'+uri(svg,'image/svg+xml')+'" alt="'+esc(caption)+'"><figcaption>'+esc(caption)+'</figcaption>'+detail('Original matching legend','<p>'+esc(Path(legend).read_text()).replace('\n\n','</p><p>')+'</p>')+'</figure>'

