JS=r'''
'use strict';
const data=JSON.parse(document.getElementById('guide-data').textContent);
const $=id=>document.getElementById(id);
const safe=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=x=>x==null?'undefined':Number(x).toFixed(4);
function makeTable(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th>'+safe(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+safe(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
const select=$('fish-select');
for(const fish of data.fish){let option=document.createElement('option');option.value=fish.fish_id;option.textContent=fish.fish_id+' · '+fish.condition_id;select.append(option);}
function showFish(){
 const id=select.value,fish=data.fish.find(x=>x.fish_id===id),score=data.scores.find(x=>x.fish_id===id),decisions=data.decisions.filter(x=>x.fish_id===id);
 $('fish-card').src='data:image/svg+xml;base64,'+data.cards[id];$('fish-card').alt='Original full atlas card for '+id+' ('+fish.condition_id+')';
 $('fish-details').innerHTML='<h4>Saved decisions for '+safe(id)+'</h4>'+makeTable(['Rule','Decision','Pre / middle / late counts','Acquisition / recovery','Score / threshold','Eligibility reason'],decisions.map(x=>[x.variant,x.decision,[x.pre_trials,x.middle_trials,x.late_trials].join(' / '),number(x.acquisition)+' / '+number(x.recovery),number(x.score)+' / '+number(x.threshold),x.eligibility_reason]))+
 '<p><b>Separate descriptive G score:</b> '+number(score.acquisition_score)+'; Pre '+score.pre_n+'/10; late Train '+score.late_training_n+'/25; defined G trials '+score.G_trials+'/90. This score does not generate the legacy labels above.</p>'+makeTable(['Attribute','Recorded value'],['acquisition_status','protocol_review_flag','coordinate_valid_fraction','derivative_valid_fraction','any_block_6','all_blocks_6','baseline_3','cr_3','train_us','last_us_exact_status','last_us_exact_reason','scope_status'].map(key=>[key,fish[key]]));
 $('score-arithmetic').innerHTML='<p>Selected fish: <b>'+safe(id)+'</b> ('+safe(fish.condition_id)+'). Change the selector in chapter 5 to inspect another fish.</p><div class="formula">median Pre y = '+number(score.pre_median)+' ('+score.pre_n+'/10 defined trials)\nmedian late Train y = '+number(score.late_training_median)+' ('+score.late_training_n+'/25 defined trials)\nA = '+number(score.pre_median)+' − ('+number(score.late_training_median)+') = '+number(score.acquisition_score)+'</div>';
}
select.value='20240618_08';select.addEventListener('change',showFish);showFish();
for(const b of document.querySelectorAll('.fish-shortcut'))b.addEventListener('click',()=>{select.value=b.dataset.fish;showFish();});
$('failure-table').innerHTML=makeTable(['Rule','Condition','Fish','Exact reason'],data.decisions.filter(x=>x.decision==='Unclassified').map(x=>[x.variant,x.condition_id,x.fish_id,x.eligibility_reason]));
$('bound-source-count').textContent='This guide binds '+Object.keys(data.sources).length+' source files. Complete paths and SHA-256 hashes are in the companion bound-inputs.json; a selected state, not a filename date, selects the current figure.';
function toy(){const v={};for(const key of ['observed','group','se','sd']){v[key]=Number($('toy-'+key).value);$('toy-'+key+'-value').textContent=v[key].toFixed(2);}const w=v.sd*v.sd/(v.sd*v.sd+v.se*v.se),pred=v.group+w*(v.observed-v.group);for(const [key,value]of [['observed',v.observed],['group',v.group],['blup',pred]])$('toy-dot-'+key).style.left=Math.max(0,Math.min(100,(value+.4)*100))+'%';$('toy-result').textContent='Toy prediction '+pred.toFixed(3)+' · individual deviation weight '+(w*100).toFixed(1)+'%';}
for(const key of ['observed','group','se','sd'])$('toy-'+key).addEventListener('input',toy);toy();
$('expand-all').addEventListener('click',()=>document.querySelectorAll('details').forEach(d=>d.open=true));
$('collapse-all').addEventListener('click',()=>document.querySelectorAll('details').forEach(d=>d.open=false));
$('print').addEventListener('click',()=>window.print());
const prompts=[['question','What exactly do I mean by acquisition/learner? Is recovery required?'],['outcome','Which outcome and transformation do I choose, and why? What does no-bout behavior mean?'],['cohort','Which technical exclusions and analysis eligibility rules are justified? Which fish remain explicitly unclassified?'],['method','Which method would I choose? What matched-estimand comparisons and sensitivity results support it?'],['uncertainty','What uncertainty/calibration evidence do I require? Which assumptions or validation failures remain?'],['threshold','Do I want continuous results or categories? If categories, what effect margin, reference, multiplicity and interpretation?'],['examples','Which fish would I illustrate, and why? Are all others accessible?'],['panels','What belongs in each main/supplementary panel? What stays in Figure 4?'],['freeze','Which exact analysis, artifact versions, legend and scoped approvals would I eventually freeze?'],['unresolved','What is missing or still unclear before I decide?']];
for(const [key,title]of prompts){const l=document.createElement('label');l.htmlFor='note-'+key;l.textContent=title;const t=document.createElement('textarea');t.id='note-'+key;t.dataset.note=key;t.placeholder='My reasoning, evidence and unresolved questions…';$('worksheet').append(l,t);}
const checks=['I can explain the outcome and its sign without relying on a badge.','I can distinguish primary cohort, outcome eligibility and classifier eligibility.','I have reviewed all learner/nonlearner/unclassified denominators.','I know which observations enter acquisition, recovery and evaluation.','I understand the selected uncertainty and reference/calibration claims.','I have reviewed method assumptions and sensitivity/validation failures.','I have justified example selection and the complete supplementary atlas.','I have checked that Figure 4 owns group behavioral comparisons.','I have identified exact source-bound SVG, legend and data versions.','I have resolved scientific choices separately from presentation checks.'];
checks.forEach((text,i)=>{const l=document.createElement('label'),c=document.createElement('input'),s=document.createElement('span');c.type='checkbox';c.dataset.check=String(i);s.textContent=text;l.append(c,s);$('freeze-checks').append(l);});
const noteKey='figure3-independent-review-guide-notes-v1';
function values(){return {schema:'figure3-review-notes/1',guide_date:'2026-10-17',saved_at:new Date().toISOString(),notes:Object.fromEntries([...document.querySelectorAll('[data-note]')].map(x=>[x.dataset.note,x.value])),checks:[...document.querySelectorAll('[data-check]')].map(x=>x.checked)};}
function restore(value){if(value.schema!=='figure3-review-notes/1')throw Error('Unrecognized notes format');for(const x of document.querySelectorAll('[data-note]'))x.value=typeof value.notes?.[x.dataset.note]==='string'?value.notes[x.dataset.note]:'';for(const x of document.querySelectorAll('[data-check]'))x.checked=Boolean(value.checks?.[Number(x.dataset.check)]);}
function save(){try{localStorage.setItem(noteKey,JSON.stringify(values()));$('notes-status').textContent='Notes saved in this browser. Export JSON for a portable copy.';}catch(e){$('notes-status').textContent='Browser storage unavailable. Use Export to keep your notes.';}}
try{const existing=localStorage.getItem(noteKey);if(existing)restore(JSON.parse(existing));}catch(e){$('notes-status').textContent='Browser storage unavailable or old notes unreadable; export your notes explicitly.';}
for(const x of document.querySelectorAll('[data-note]'))x.addEventListener('input',save);for(const x of document.querySelectorAll('[data-check]'))x.addEventListener('change',save);
$('export-notes').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(values(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='figure3-my-review-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('import-notes').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;restore(JSON.parse(await file.text()));save();$('notes-status').textContent='Imported review notes; nothing was approved or frozen.';}catch(error){$('notes-status').textContent='Import failed: '+error.message;}});
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}},{rootMargin:'-10% 0px -70% 0px'});document.querySelectorAll('main section').forEach(s=>observer.observe(s));
'''

